LOVE = ("a face with little hearts around it", "icon:love-face"); JAR = ("an empty glass jar", "icon:jar")
ROCK = ("a grey rock", "icon:rock"); BRICK = ("a red brick", "icon:brick"); LOG = ("a wooden log", "icon:log")
HOURGLASS = ("an hourglass with sand", "icon:hourglass"); CALENDAR = ("a calendar page", "icon:calendar")
